// Нормализация ошибки: не сохраняем токены и секреты в payload
const e = $input.first().json;
const execution = e.execution ?? {};
const workflow = e.workflow ?? {};
const lastNode = execution.lastNodeExecuted ?? null;
const message = (e.error?.message ?? execution.error?.message ?? 'unknown error').slice(0, 2000);

const runData = execution.data?.resultData?.runData ?? {};
let workspaceId = null;
let jobId = null;
for (const nodeName of Object.keys(runData)) {
  for (const run of runData[nodeName] ?? []) {
    const items = run?.data?.main?.[0] ?? [];
    for (const item of items) {
      workspaceId = workspaceId ?? item?.json?.workspace_id ?? null;
      jobId = jobId ?? item?.json?.job_id ?? item?.json?.id ?? null;
    }
  }
}

return [{ json: {
  workflow_name: workflow.name ?? null,
  execution_id: execution.id ?? null,
  last_node: lastNode,
  error_message: message,
  workspace_id: workspaceId,
  job_id: jobId,
  occurred_at: new Date().toISOString(),
}}];
